func expandVertexAISemanticGovernancePolicyMcpTools(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (interface{}, error) {
	if v == nil {
		return nil, nil
	}
	l := v.([]interface{})
	req := make([]interface{}, 0, len(l))
	for _, raw := range l {
		if raw == nil {
			continue
		}
		original := raw.(map[string]interface{})
		transformed := make(map[string]interface{})

		transformedMcpServer, err := expandVertexAISemanticGovernancePolicyMcpToolsMcpServer(original["mcp_server"], d, config)
		if err != nil {
			return nil, err
		} else if val := reflect.ValueOf(transformedMcpServer); val.IsValid() && !tpgresource.IsEmptyValue(val) {
			transformed["mcpServer"] = transformedMcpServer
		}

		transformedTools, err := expandVertexAISemanticGovernancePolicyMcpToolsTools(original["tools"], d, config)
		if err != nil {
			return nil, err
		} else if val := reflect.ValueOf(transformedTools); val.IsValid() && !tpgresource.IsEmptyValue(val) {
			transformed["tools"] = transformedTools
		}

		req = append(req, transformed)
	}
	return req, nil
}

