func ResourceVertexAISemanticGovernancePolicyFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("name", flattenVertexAISemanticGovernancePolicyName(res["name"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("create_time", flattenVertexAISemanticGovernancePolicyCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("update_time", flattenVertexAISemanticGovernancePolicyUpdateTime(res["updateTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("etag", flattenVertexAISemanticGovernancePolicyEtag(res["etag"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("display_name", flattenVertexAISemanticGovernancePolicyDisplayName(res["displayName"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("description", flattenVertexAISemanticGovernancePolicyDescription(res["description"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("natural_language_constraint", flattenVertexAISemanticGovernancePolicyNaturalLanguageConstraint(res["naturalLanguageConstraint"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("agent", flattenVertexAISemanticGovernancePolicyAgent(res["agent"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("mcp_tools", flattenVertexAISemanticGovernancePolicyMcpTools(res["mcpTools"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("agent_identity", flattenVertexAISemanticGovernancePolicyAgentIdentity(res["agentIdentity"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}
	if err = d.Set("agent_response_customization", flattenVertexAISemanticGovernancePolicyAgentResponseCustomization(res["agentResponseCustomization"], d, config)); err != nil {
		return fmt.Errorf("Error reading SemanticGovernancePolicy: %s", err)
	}

	return nil
}
